/*
 * ringkit — polyphase resampler (48k → 16k decimator).
 *
 * The coefficient tables live in ring_ws_resample.c (generated by
 * tools/gen_ws_resampler.py) and are shared with ring_ws via extern.
 */
#include "ringkit/ring_resample.h"
#include <string.h>

/* Coefficients generated by tools/gen_ws_resampler.py — 3 phases × 21 taps. */
extern const float ring_ws_decim_coeffs[RING_RESAMPLE_DECIM_PHASES][RING_RESAMPLE_DECIM_PHASE_LEN];

void ring_resample_decim_init(ring_resample_decim_state_t *s)
{
    memset(s->history, 0, sizeof(s->history));
}

int ring_resample_decim_process(ring_resample_decim_state_t *s,
                                 const float *input, int n_in,
                                 float *output)
{
    int n_out = 0;
    int want = n_in / RING_RESAMPLE_DECIM_PHASES;
    const float *hist = s->history;
    int hlen = RING_RESAMPLE_DECIM_HIST_LEN;

    for (int n = 0; n < want; n++) {
        float acc = 0.0f;
        for (int p = 0; p < RING_RESAMPLE_DECIM_PHASES; p++) {
            const float *cp = ring_ws_decim_coeffs[p];
            for (int k = 0; k < RING_RESAMPLE_DECIM_PHASE_LEN; k++) {
                int t = RING_RESAMPLE_DECIM_PHASES * n - p - RING_RESAMPLE_DECIM_PHASES * k;
                float x;
                if (t < 0) {
                    int hidx = t + hlen;
                    x = (hidx >= 0 && hidx < hlen) ? hist[hidx] : 0.0f;
                } else if (t < n_in) {
                    x = input[t];
                } else {
                    x = 0.0f;
                }
                acc += x * cp[k];
            }
        }
        output[n_out++] = acc;
    }

    /* Keep the last HIST_LEN samples for the next call. */
    int keep = hlen;
    int total = hlen + n_in;
    int src = total - keep;
    for (int i = 0; i < keep; i++) {
        if (src + i < hlen) {
            s->history[i] = hist[src + i];
        } else if (src + i - hlen < n_in) {
            s->history[i] = input[src + i - hlen];
        } else {
            s->history[i] = 0.0f;
        }
    }

    return n_out;
}